const email = env.get("RAYVN_EMAIL");
const password = env.get("RAYVN_PASSWORD");

if (!email || !password) {
    node.warn("[BOOST] RAYVN_EMAIL or RAYVN_PASSWORD not set");
    return null;
}

msg.url = "https://login.rayvn.global/oauth/token";
msg.headers = { "Content-Type": "application/json" };
msg.payload = {
    grant_type: "password",
    client_id: "s2lU2X0OtR9LflGlXaohRSHZmLbCWq0E",
    username: email,
    password: password,
    scope: "openid profile email"
};
return msg;

const id_token = msg.payload.id_token;
if (!id_token) {
    node.warn("[BOOST] ROPC login failed: no id_token");
    return null;
}

const parts = id_token.split('.');
const payload = JSON.parse(Buffer.from(parts[1], 'base64url').toString());

msg.smallAuthToken = payload.authToken;
msg.project = payload.projects[0];

msg.url = msg.project.apiUrl + "/restapi/authProfile/" + msg.project.userId;
msg.headers = { "Authorization": "Bearer " + msg.smallAuthToken };
msg.payload = {};  // POST with empty body                        
return msg;

const profile = msg.payload;
const sas = profile.environmentProperties.azureStorage;

const session = {
    enrichedToken: profile.authToken,
    imagesAccessToken: sas.imagesAccessToken,
    filesAccessToken: sas.filesAccessToken,
    userId: profile.user.id,
    projectId: profile.project.id,
    apiUrl: msg.project.apiUrl,
    refreshedAt: Date.now(),
    expiresAt: Date.now() + (20 * 60 * 1000)
};

global.set("parat_bridge.ropc_session", session);
global.set("parat_bridge.boost_mode", true);

node.status({ fill: "green", shape: "dot", text: "refreshed " + new Date().toLocaleTimeString() });
node.warn("[BOOST] Session refreshed. Expires ~" + new Date(session.expiresAt).toLocaleTimeString());

msg.payload = session;
return msg;
